class Solution {
  public int countWays(List<Integer> nums) {
    int n = nums.size();
    int[] cnt = new int[n + 1];
    for (int x : nums) cnt[x]++;
    int ways = 0, less = 0;
    for (int k = 0; k <= n; k++) {
      if (less == k && cnt[k] == 0) ways++;
      less += cnt[k];
    }
    return ways;
  }
}
